const campaign = $('Extract Campaign Data').first().json;
const lead = $('Companies Email Leads').first().json;

const isArabic = campaign.language === 'Arabic';

const subject = isArabic
  ? campaign.subjectArabic
  : campaign.subjectEnglish;

const content = isArabic
  ? campaign.emailContentArabic
  : campaign.emailContentEnglish;

const ctaText = isArabic
  ? campaign.ctaTextArabic || 'احجز استشارة مجانية'
  : campaign.ctaTextEnglish || 'Book Free Consultation';

const footer = isArabic
  ? campaign.footerArabic
  : campaign.footerEnglish;

const websiteUrl = isArabic
  ? 'https://businesspartner.sa/ar/'
  : 'https://businesspartner.sa/en/';

const whatsappUrl = 'https://wa.me/966507034157';

const finalContent = (content || '')
  .replaceAll('{company_name}', lead.name || '')
  .replaceAll('{contact_name}', lead.property_contact_name || (isArabic ? 'السادة' : 'Sir/Madam'))
  .replaceAll('\n', '<br>');

const finalFooter = (footer || '').replaceAll('\n', '<br>');

const htmlBody = `
<div dir="${isArabic ? 'rtl' : 'ltr'}"
style="
direction:${isArabic ? 'rtl' : 'ltr'};
unicode-bidi:embed;
font-family:Tahoma,Arial,sans-serif;
max-width:800px;
margin:auto;
padding:30px;
font-size:18px;
line-height:2;
color:#1f2937;
text-align:${isArabic ? 'right' : 'left'};
">

  <div style="text-align:center;margin-bottom:24px;">
    <img src="${campaign.headerLogoUrl}"
    alt="Business Partner"
    style="max-width:220px;height:auto;display:block;margin:auto;">
  </div>

  <div style="text-align:center;margin-bottom:32px;">
    <img src="${campaign.bannerImageUrl}"
    alt="Business Partner Banner"
    style="width:100%;max-width:800px;height:auto;display:block;border-radius:12px;margin:auto;">
  </div>

  <div style="font-size:18px;line-height:2;margin-bottom:30px;">
    ${finalContent}
  </div>

  <div style="text-align:center;margin:34px 0;">

    <a href="${websiteUrl}"
    style="
    background:${campaign.brandPrimaryColor || '#08145F'};
    color:#ffffff;
    padding:14px 32px;
    border-radius:8px;
    text-decoration:none;
    font-weight:bold;
    display:inline-block;
    font-size:16px;
    margin:8px;
    ">
      ${ctaText}
    </a>

    <a href="${whatsappUrl}"
    style="
    background:#25D366;
    color:#ffffff;
    padding:14px 32px;
    border-radius:8px;
    text-decoration:none;
    font-weight:bold;
    display:inline-block;
    font-size:16px;
    margin:8px;
    ">
      ${isArabic ? 'تواصل عبر واتساب' : 'Contact via WhatsApp'}
    </a>

  </div>

  <hr style="border:none;border-top:1px solid #e5e7eb;margin:34px 0;">

  <div style="font-size:14px;color:#6b7280;line-height:1.9;text-align:${isArabic ? 'right' : 'left'};">
    ${finalFooter}<br><br>

    <a href="${websiteUrl}">businesspartner.sa</a><br><br>

    <a href="${campaign.linkedInUrl}">LinkedIn</a> |
    <a href="${campaign.instagramUrl}">Instagram</a> |
    <a href="${campaign.facebookUrl}">Facebook</a>
  </div>

</div>
`;

return [{
  json: {
    subject,
    body: htmlBody
  }
}];
